import { render } from '@solidjs/web';
import { createSignal, createMemo, Loading, isPending } from 'solid-js';

async function fetchUser(id) {
  await new Promise((resolve) => setTimeout(resolve, 500));
  return { id, name: `Explorer ${id}`, joined: 2020 + (Number(id) % 6) };
}

function Profile() {
  const [userId, setUserId] = createSignal('1');
  const user = createMemo(() => ({ id: userId(), name: 'Placeholder', joined: 0 }));

  return (
    <>
      <label>
        User ID{' '}
        <input
          type="number"
          min="1"
          value={userId()}
          onInput={(event) => setUserId(event.currentTarget.value)}
        />
      </label>
      <Loading fallback={<p>Loading user...</p>}>
        <h2>
          {user().name} {isPending(user) ? '(updating...)' : ''}
        </h2>
        <p>Joined in {user().joined}</p>
      </Loading>
    </>
  );
}

render(() => <Profile />, document.getElementById('app'));

